/**
 * Model User
 * A team member. Created on first successful sign-in through the configured
 * auth provider (Ion in production). `role` is the single source of truth for
 * authorization and is only ever read server-side.
 */
export type User = $Result.DefaultSelection<Prisma.$UserPayload>
/**
 * Model Session
 * Server-side session. The browser only ever holds an opaque random token;
 * only its SHA-256 hash is stored, so a database leak cannot be replayed.
 */
export type Session = $Result.DefaultSelection<Prisma.$SessionPayload>
/**
 * Model AuthRequest
 * Short-lived record binding an in-flight OAuth authorization request to this
 * browser. Holds the PKCE verifier so it never travels to the client.
 */
export type AuthRequest = $Result.DefaultSelection<Prisma.$AuthRequestPayload>
/**
 * Model Tournament
 * 
 */
export type Tournament = $Result.DefaultSelection<Prisma.$TournamentPayload>
/**
 * Model TournamentDivision
 * An event/division a member can register for at a given tournament.
 */
export type TournamentDivision = $Result.DefaultSelection<Prisma.$TournamentDivisionPayload>
/**
 * Model TournamentRegistration
 * 
 */
export type TournamentRegistration = $Result.DefaultSelection<Prisma.$TournamentRegistrationPayload>
/**
 * Model DuesRecord
 * A per-season override for one member, not a ledger. What a member owes is
 * computed from their unpaid tournament fees and unpaid orders — see
 * lib/services/dues.ts — and reaches $0 as soon as every item is checked off
 * on their profile. This row exists only to excuse a member from paying at
 * all (a hardship waiver) and to leave the treasurer a note; most members
 * never have one.
 */
export type DuesRecord = $Result.DefaultSelection<Prisma.$DuesRecordPayload>
/**
 * Model OrderItem
 * Catalog entry an officer can create without touching source code.
 */
export type OrderItem = $Result.DefaultSelection<Prisma.$OrderItemPayload>
/**
 * Model Order
 * 
 */
export type Order = $Result.DefaultSelection<Prisma.$OrderPayload>
/**
 * Model Achievement
 * 
 */
export type Achievement = $Result.DefaultSelection<Prisma.$AchievementPayload>
/**
 * Model Award
 * An award attributed to one member. Optionally derived from a public
 * Achievement so the two stay linked without duplicating text.
 */
export type Award = $Result.DefaultSelection<Prisma.$AwardPayload>
/**
 * Model NewsPost
 * 
 */
export type NewsPost = $Result.DefaultSelection<Prisma.$NewsPostPayload>
/**
 * Model OfficerProfile
 * 
 */
export type OfficerProfile = $Result.DefaultSelection<Prisma.$OfficerProfilePayload>
/**
 * Model Resource
 * 
 */
export type Resource = $Result.DefaultSelection<Prisma.$ResourcePayload>
/**
 * Model ClubSetting
 * Officer-editable club facts (contact address, socials, dues amount, links).
 * Keeps content changes out of the source tree.
 */
export type ClubSetting = $Result.DefaultSelection<Prisma.$ClubSettingPayload>
/**
 * Model AuditLog
 * Append-only record of administrative actions. Rows are never updated.
 */
export type AuditLog = $Result.DefaultSelection<Prisma.$AuditLogPayload>

